function s(v){return String(v==null?'':v).trim();}
function norm(x){return s(x).toLowerCase().replace(/[^a-z0-9]/g,'');}
const el=$('Read ERROR LOG').all().map(i=>i.json);
const rawTh=$('Read Thesis correction').all().map(i=>{const o=i.json;return Object.keys(o).filter(k=>k!=='row_number').map(k=>o[k]);});
const inv=$('Read INVESTORS').all().map(i=>i.json);
const trk=$('Read Deal Tracker').all().map(i=>i.json);
const st=$('Read STARTUPS').all().map(i=>i.json);
const pipe=$input.all().map(i=>i.json);

const thesisWatchAll=el.filter(r=>s(r.workflow)==='THESIS-WATCH').map(r=>({row_number:r.row_number,timestamp:s(r.timestamp),investor:s(r.investor),error_type:s(r.error_type),resolved:s(r.resolved)}));
const open=el.filter(r=>s(r.workflow)==='THESIS-WATCH'&&s(r.resolved)==='').map(r=>({row_number:r.row_number,timestamp:s(r.timestamp),investor:s(r.investor),error_type:s(r.error_type),details:s(r.details)}));

let P=null;
for(const r of rawTh){const idx=r.findIndex(c=>s(c).toLowerCase()==='sector');if(idx>0){P={firm:0,contact:1,email:2,sector:idx,stage:idx+1,cheque:idx+2,geo:idx+3,arr:idx+4};break;}}
const thesis=[];
if(P){for(const r of rawTh){const firm=s(r[P.firm]);if(!firm||firm.toLowerCase()==='firm name')continue;thesis.push({firm:firm,contact:s(r[P.contact]),email:s(r[P.email]),sector:s(r[P.sector]),stage:s(r[P.stage]),cheque:s(r[P.cheque]),geo:s(r[P.geo]),arr:s(r[P.arr])});}}

const tcols=Object.keys(trk[0]||{});
let cInv=null;const cDeals=[];
for(const c of tcols){const l=c.toLowerCase();if(!cInv&&(l.indexOf('investor')>=0||l.indexOf('vc name')>=0)){cInv=c;}if(l.indexOf('deals shared')>=0||l.indexOf('latest deal')>=0||l.indexOf('picked')>=0){cDeals.push(c);}}
const distinctInv={};for(const r of trk){const k=norm(r[cInv]);if(k)distinctInv[k]=1;}

const flagged={};
for(const f of open){const k=norm(f.investor);const firstTok=norm(s(f.investor).split(/\s+/)[0]);
 const hits=inv.filter(r=>{const n=norm(r.investor);return n===k||(k.length>=5&&(n.indexOf(k)>=0||k.indexOf(n)>=0&&n.length>=5))||(firstTok.length>=4&&n.indexOf(firstTok)===0);});
 const emails={};for(const h of hits){if(s(h.email))emails[s(h.email).toLowerCase()]=1;}
 const sibling=inv.filter(r=>emails[s(r.email).toLowerCase()]&&hits.indexOf(r)<0);
 const allRec=hits.concat(sibling);
 const names={};for(const h of allRec)names[s(h.investor)]=1;
 const prow=pipe.filter(p=>names[s(p.investor)]).map(p=>({row_number:p.row_number,deal_id:s(p.deal_id),investor:s(p.investor),startup:s(p.startup),deal_shared:s(p.deal_shared),investor_response:s(p.investor_response).slice(0,60),pause:s(p.pause),next_due:s(p.next_due),next_action:s(p.next_action),priority:s(p.priority),email:s(p.email),notes:s(p.notes).slice(0,90)}));
 const tr=[];for(const r of trk){const n=norm(r[cInv]);if(!n)continue;if(n===k||(k.length>=5&&(n.indexOf(k)>=0||k.indexOf(n)>=0&&n.length>=5))||(firstTok.length>=4&&n.indexOf(firstTok)===0)){const o={row_number:r.row_number};for(const c of tcols){if(s(r[c]))o[c]=s(r[c]).slice(0,500);}tr.push(o);}}
 const th=thesis.filter(t=>{const n=norm(t.firm);return n===k||(n.length>=5&&(k.indexOf(n)>=0||n.indexOf(k)>=0))||(firstTok.length>=4&&n.indexOf(firstTok)===0);});
 flagged[f.investor]={investors_rows:allRec,thesis_rows:th,pipeline_rows:prow,tracker_rows:tr};}

let maxN=0;for(const p of pipe){const id=s(p.deal_id);if(id.charAt(0)==='D'){const v=parseInt(id.slice(1),10);if(!isNaN(v)&&v>maxN)maxN=v;}}
const scols=Object.keys(st[0]||{});
const startups=st.filter(r=>s(r.active).toLowerCase()==='yes').map(r=>({startup:s(r.startup),owner:s(r.owner),sector:s(r.sector).slice(0,160),stage:s(r.stage).slice(0,80),raise_inr_cr:s(r.raise_inr_cr),arr:s(r.arr||r.revenue||'').slice(0,60),geo:s(r.geography||r.location||'').slice(0,40)}));
const load={};for(const p of pipe){if(s(p.deal_shared).toLowerCase()==='yes'||s(p.pause).toLowerCase()==='yes')continue;const d=s(p.next_due);if(d)load[d]=(load[d]||0)+1;}
return [{json:{error_log_rows:el.length,thesis_watch_all:thesisWatchAll,open_flags:open,thesis_label_found:!!P,thesis_count:thesis.length,investors_rows:inv.length,investor_columns:Object.keys(inv[0]||{}),tracker_rows:trk.length,tracker_distinct_investors:Object.keys(distinctInv).length,tracker_columns:tcols,tracker_inv_col:cInv,tracker_deal_cols:cDeals,pipeline_rows:pipe.length,pipeline_columns:Object.keys(pipe[0]||{}),max_deal_num:maxN,startups_total:st.length,startup_columns:scols,active_startups:startups,flagged:flagged,pending_load_by_date:load}}];
